package app.tonal.android;

import android.app.*;
import android.content.*;
import android.os.*;
import android.text.InputType;
import android.view.*;
import android.view.inputmethod.*;
import android.widget.*;
import org.json.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.function.Consumer;

/** Touch catalog for independent sources, with explicit identities and no false exclusivity claims. */
public final class IndieActivity extends Activity {
    private Ui ui;private IndieCatalog catalog;private Artwork artwork;private EditText queryInput;
    private LinearLayout content,filters;private TextView summary,now;private ScrollView scroll;
    private String query="",source=IndieCatalog.SOURCES[0],filter="all";private IndieCatalog.Item route;
    private int page;private boolean destroyed;private final ArrayList<IndieCatalog.Item> items=new ArrayList<>();
    private final Map<String,String> errors=new LinkedHashMap<>();private final Map<String,Boolean> more=new HashMap<>();
    private final ArrayDeque<IndieCatalog.Item> history=new ArrayDeque<>();
    private final Consumer<String> statusListener=text->updateTransport();
    private final Handler handler=new Handler(Looper.getMainLooper());
    private final Runnable ticker=new Runnable(){public void run(){updateTransport();handler.postDelayed(this,1000);}};
    @Override public void onCreate(Bundle saved){super.onCreate(saved);getWindow().setStatusBarColor(Ui.BG);getWindow().setNavigationBarColor(Ui.BG);ui=new Ui(this);Diagnostics.initialize(this,"indie");NativeBridge.audio.initialize(this,"indie-audio");catalog=new IndieCatalog(this);artwork=new Artwork(this);build();IndiePlaybackService.listeners.add(statusListener);
        if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,this::back);
        if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},10);
        acceptIntent(getIntent());
    }
    private void build(){LinearLayout root=ui.column();root.setBackgroundColor(Ui.BG);Ui.insets(root);LinearLayout header=ui.row();ui.pad(header,12,8);ui.weight(header,ui.title("IndieTonal",23));header.addView(ui.icon("home","Tonal Hub",()->HubActivity.open(this,HubActivity.class,"")));header.addView(ui.icon("heart","Biblioteca pessoal, estatísticas e letras",()->MusicPanel.show(this)));header.addView(ui.icon("audio","Áudio",()->AudioPanel.show(this)));header.addView(ui.icon("account","Conexões",this::connections));root.addView(header);
        LinearLayout switcher=ui.row();ui.pad(switcher,12,4);ui.weight(switcher,ui.action("Tonalify • Spotify",()->HubActivity.open(this,MainActivity.class,query)));ui.weight(switcher,ui.action("Voltar",this::back));root.addView(switcher);
        LinearLayout search=ui.row();ui.pad(search,12,4);queryInput=new EditText(this);queryInput.setTextColor(Ui.TEXT);queryInput.setHintTextColor(Ui.MUTED);queryInput.setHint("Artista, álbum ou música");queryInput.setSingleLine();queryInput.setImeOptions(EditorInfo.IME_ACTION_SEARCH);ui.weight(search,queryInput);search.addView(ui.action("Buscar",this::search));queryInput.setOnEditorActionListener((v,a,e)->{if(a==EditorInfo.IME_ACTION_SEARCH){search();return true;}return false;});root.addView(search);
        Spinner provider=new Spinner(this);provider.setContentDescription("Fonte de catálogo");provider.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,IndieCatalog.SOURCES));provider.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?> p,View v,int n,long id){String next=IndieCatalog.SOURCES[n];if(!source.equals(next)){source=next;route=null;history.clear();filter="all";load(false);}}public void onNothingSelected(AdapterView<?> p){}});root.addView(provider);
        HorizontalScrollView strip=new HorizontalScrollView(this);strip.setHorizontalScrollBarEnabled(false);filters=ui.row();strip.addView(filters);root.addView(strip);summary=ui.text("Busque um artista ou explore shows ao vivo.",12,Ui.MUTED);ui.pad(summary,14,8);root.addView(summary);
        scroll=new ScrollView(this);content=ui.column();ui.pad(content,14,4);scroll.addView(content);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
        LinearLayout transport=ui.column();ui.pad(transport,12,8);ui.rounded(transport,Ui.PANEL,8);now=ui.text("",13,Ui.TEXT);now.setMaxLines(3);transport.addView(now);LinearLayout controls=ui.row();ui.weight(controls,ui.action("Anterior",()->IndiePlaybackService.start(this,"prev")));ui.weight(controls,ui.action("Reproduzir / pausar",()->IndiePlaybackService.start(this,"toggle")));ui.weight(controls,ui.action("Próxima",()->IndiePlaybackService.start(this,"next")));controls.addView(ui.icon("more","Parar motor de áudio",()->stopService(new Intent(this,IndiePlaybackService.class))));transport.addView(controls);root.addView(transport);setContentView(root);render();updateTransport();}
    void searchArtist(String name){queryInput.setText(name);search();}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);MusicPanel.photoResult(this,request,result,data);MusicPanel.backupResult(this,request,result,data);}
    private void search(){query=queryInput.getText().toString().trim();if(query.isEmpty())return;if(query.length()>200)query=query.substring(0,200);route=null;history.clear();filter="all";((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(queryInput.getWindowToken(),0);load(false);}
    private void load(boolean append){if(query.isBlank()&&route==null){render();return;}if(!append){page=0;items.clear();errors.clear();more.clear();}summary.setText("Consultando "+(route==null?source:route.source)+"…");int requestedPage=page;IndieCatalog.Item requestedRoute=route;catalog.load(query,source,route,page,b->{if(destroyed)return;errors.remove(b.source);if(!b.error.isEmpty())errors.put(b.source,b.error);if(b.stale)errors.put(b.source,"Cópia recente do catálogo: a fonte está temporariamente indisponível.");more.put(b.source,b.more);Set<String> keys=new HashSet<>();for(IndieCatalog.Item i:items)keys.add(i.key());for(IndieCatalog.Item i:b.items)if(keys.add(i.key()))items.add(i);if(route==null)IndieCatalog.sort(items,query);render();});render();}
    private boolean visible(IndieCatalog.Item i){return filter.equals("all")||filter.equals(i.kind)||(filter.equals("album")&&(i.kind.equals("playlist")||i.kind.equals("release")));}
    private void render(){if(content==null)return;filters.removeAllViews();String[] kinds={"all","artist","show","demo","recording","album","track"},names={"Tudo","Artistas","Shows","Demos","Gravações","Álbuns","Músicas"};for(int n=0;n<kinds.length;n++){String key=kinds[n];int count=0;String previous=filter;filter=key;for(IndieCatalog.Item i:items)if(visible(i))count++;filter=previous;TextView chip=ui.pill(names[n]+" ("+count+")",filter.equals(key),()->{filter=key;render();});ui.pad(chip,10,10);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-2,-2);p.setMargins(ui.dp(4),0,ui.dp(4),0);filters.addView(chip,p);}
        content.removeAllViews();if(route!=null){content.addView(ui.title(route.title,23));content.addView(ui.text(route.artist+" • "+route.source,13,Ui.MUTED));ui.space(content,12);}
        for(Map.Entry<String,String> entry:errors.entrySet()){TextView text=ui.text(entry.getKey()+": "+entry.getValue(),13,0xffffc26c);content.addView(text);content.addView(ui.action("Tentar novamente • "+entry.getKey(),()->retry(entry.getKey())));}
        int count=0;for(IndieCatalog.Item item:items)if(visible(item)){addRow(item);count++;}
        if(count==0){content.addView(ui.text(query.isEmpty()?"Explore música pública, discografias e sua biblioteca. MusicBrainz informa metadados e não fornece áudio.":"Nenhum resultado carregado neste filtro. Aguarde as fontes ou tente outro nome.",15,Ui.MUTED));if(filter.equals("show")||source.equals("Live Music Archive"))content.addView(ui.text("Experimente Internet Archive ou Aadam Jacobs para shows de fãs e demos. Confira o artista: homônimos e tributos são identificados como relacionados.",13,Ui.MUTED));}
        boolean next=false;for(boolean value:more.values())next|=value;if(next)content.addView(ui.action("Carregar mais",()->{page++;load(true);}));
        summary.setText((route==null?query:route.title)+" • "+items.size()+" resultados");
    }
    private void retry(String provider){catalog.load(query,provider,route,page,b->{errors.remove(provider);if(!b.error.isEmpty())errors.put(provider,b.error);more.put(provider,b.more);Set<String> keys=new HashSet<>();for(IndieCatalog.Item i:items)keys.add(i.key());for(IndieCatalog.Item i:b.items)if(keys.add(i.key()))items.add(i);if(route==null)IndieCatalog.sort(items,query);render();});}
    private void addRow(IndieCatalog.Item i){LinearLayout row=ui.row();ui.pad(row,8,10);ui.rounded(row,Ui.CARD,8);if(!i.image.isEmpty()){ImageView art=new ImageView(this);art.setScaleType(ImageView.ScaleType.CENTER_CROP);row.addView(art,new LinearLayout.LayoutParams(ui.dp(52),ui.dp(52)));artwork.load(art,i.image);}LinearLayout labels=ui.column();ui.pad(labels,10,0);TextView name=ui.title(i.title,15);name.setMaxLines(2);labels.addView(name);labels.addView(ui.text((i.artist.isEmpty()?"":i.artist+" • ")+i.source+" • "+kindName(i.kind),12,Ui.MUTED));TextView detail=ui.text(i.detail,12,Ui.MUTED);detail.setMaxLines(3);labels.addView(detail);ui.weight(row,labels);if(i.playable)row.addView(ui.icon("heart","Favoritar "+i.title,()->{MusicStore store=MusicStore.get(this);store.favorite(i.saved(),!store.liked(i.saved()));notice("Favoritos atualizados");}));if(i.playable)row.addView(ui.icon("play","Reproduzir "+i.title,()->play(i)));ui.clickable(row,()->{if(i.playable){play(i);return;}if(i.kind.equals("track")){notice("MusicBrainz informa a discografia. Esta fonte não fornece áudio.");return;}if(route!=null)history.push(route);route=i;filter="all";scroll.scrollTo(0,0);load(false);});LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=ui.dp(8);content.addView(row,p);}
    private String kindName(String kind){switch(kind){case "artist":return "Artista";case "album":return "Álbum";case "release":return "Edição";case "playlist":return "Playlist";case "show":return "Show ao vivo";case "demo":return "Demo / ensaio";case "recording":return "Gravação";default:return "Música";}}
    private void play(IndieCatalog.Item item){ArrayList<IndieCatalog.Item> queue=new ArrayList<>();for(IndieCatalog.Item i:items)if(i.playable&&visible(i))queue.add(i);int index=queue.indexOf(item);if(index<0){queue.add(item);index=queue.size()-1;}IndiePlaybackService.play(this,queue,index);}
    private void back(){if(route!=null){route=history.isEmpty()?null:history.pop();filter="all";load(false);}else HubActivity.open(this,HubActivity.class,"");}
    private void updateTransport(){if(now==null)return;now.setText(IndiePlaybackService.title+(IndiePlaybackService.artist.isEmpty()?"":" • "+IndiePlaybackService.artist)+"\n"+IndiePlaybackService.status+String.format(Locale.ROOT," • %d:%02d • reserva %.1f MiB",IndiePlaybackService.position/60000,(IndiePlaybackService.position/1000)%60,IndiePlaybackService.buffered/1048576.));}
    void notice(String message){Toast.makeText(this,message,Toast.LENGTH_LONG).show();}
    private EditText field(LinearLayout group,String label,String value,boolean secret){group.addView(ui.text(label,13,Ui.MUTED));EditText edit=new EditText(this);edit.setTextColor(Ui.TEXT);edit.setHintTextColor(Ui.MUTED);edit.setSingleLine();edit.setText(value);if(secret)edit.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);else edit.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_NO_SUGGESTIONS);group.addView(edit);return edit;}
    private void connections(){LinearLayout form=ui.column();ui.pad(form,16,12);form.addView(ui.text("Jamendo exige seu próprio client ID ativo. OpenSubsonic conecta uma biblioteca HTTPS sua, inclusive compras do Bandcamp importadas nela.",13,Ui.MUTED));JSONObject current=catalog.credentials();EditText jamendo=field(form,"Client ID Jamendo",catalog.preferences().getString("jamendo",""),false),server=field(form,"Servidor OpenSubsonic HTTPS",current.optString("server"),false),user=field(form,"Usuário da biblioteca",current.optString("user"),false),password=field(form,"Senha • em branco mantém a mesma conta","",true);ScrollView view=new ScrollView(this);view.addView(form);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Conexões IndieTonal").setView(view).setNegativeButton("Cancelar",null).setPositiveButton("Salvar",null).create();dialog.setOnShowListener(d->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{try{catalog.saveConnections(jamendo.getText().toString(),server.getText().toString(),user.getText().toString(),password.getText().toString());stopService(new Intent(this,IndiePlaybackService.class));dialog.dismiss();route=null;history.clear();load(false);notice("Conexões salvas. A senha fica cifrada no Android Keystore.");}catch(Exception error){notice("Não foi possível salvar. Confira o endereço HTTPS e os dados.");}}));dialog.show();}
    private void acceptIntent(Intent intent){String typed=intent.getStringExtra("literalQuery");if(typed!=null&&!typed.isBlank()){queryInput.setText(typed.substring(0,Math.min(200,typed.length())));search();}if(BuildConfig.DEBUG&&intent.getBooleanExtra("indieSnapshot",false))snapshot();}
    private int translatedLines(){int n=0;for(Object v:MusicStore.values(MusicStore.get(this).lines))if(!((JSONObject)v).optString("translation").isEmpty())n++;return n;}
    private void snapshot(){try{JSONArray a=new JSONArray();for(IndieCatalog.Item i:items)a.put(i.json());JSONObject o=new JSONObject().put("query",query).put("source",source).put("route",route==null?JSONObject.NULL:route.json()).put("items",a).put("playing",IndiePlaybackService.playing).put("positionMs",IndiePlaybackService.position).put("bufferedBytes",IndiePlaybackService.buffered).put("library",new JSONObject().put("favorites",MusicStore.get(this).favorites().length()).put("playlists",MusicStore.array(MusicStore.get(this).data,"playlists").length()).put("stats",MusicStore.get(this).statistics(7,"artists")).put("lyricLines",MusicStore.get(this).lines.length()).put("translatedLines",translatedLines())).put("audio",NativeBridge.audio.testSnapshot());java.nio.file.Files.write(new java.io.File(getFilesDir(),"indie-snapshot.json").toPath(),o.toString().getBytes(StandardCharsets.UTF_8));}catch(Exception e){android.util.Log.e("TonalTest","Indie snapshot failed");}}
    @Override protected void onNewIntent(Intent i){super.onNewIntent(i);setIntent(i);acceptIntent(i);}
    @Override public void onBackPressed(){back();}
    @Override protected void onStart(){super.onStart();handler.post(ticker);}
    @Override protected void onStop(){handler.removeCallbacks(ticker);super.onStop();}
    @Override protected void onDestroy(){destroyed=true;handler.removeCallbacksAndMessages(null);IndiePlaybackService.listeners.remove(statusListener);catalog.close();artwork.close();super.onDestroy();}
}
